import re, sys, zlib

path = sys.argv[1]
pat = sys.argv[2] if len(sys.argv) > 2 else None
data = open(path, 'rb').read()

pages = []
for m in re.finditer(rb'stream\r?\n', data):
    start = m.end()
    end = data.find(b'endstream', start)
    if end == -1:
        continue
    raw = data[start:end]
    try:
        txt = zlib.decompress(raw)
    except Exception:
        continue
    # pull text out of Tj / TJ operators
    out = []
    for tm in re.finditer(rb'\((?:\\.|[^\\()])*\)', txt):
        s = tm.group(0)[1:-1]
        s = s.replace(b'\\(', b'(').replace(b'\\)', b')').replace(b'\\\\', b'\\')
        out.append(s.decode('latin-1'))
    if out:
        pages.append(out)

print("PAGES_WITH_TEXT:", len(pages))
for i, out in enumerate(pages, 1):
    joined = " | ".join(out)
    if pat is None or re.search(pat, joined, re.I):
        print("=" * 20, "page", i)
        print(joined)
